def semver_sort(versions):
    def parse_version(v):
        # Split on '+' to remove build metadata
        v_no_build = v.split('+')[0]

        # Split on '-' to separate core version from pre-release
        if '-' in v_no_build:
            core_part, prerelease_part = v_no_build.split('-', 1)
        else:
            core_part = v_no_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = core_part.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        if prerelease_part:
            prerelease_ids = prerelease_part.split('.')
        else:
            prerelease_ids = None

        return (major, minor, patch, prerelease_ids)

    def prerelease_key(prerelease_ids):
        if prerelease_ids is None:
            # No pre-release: sorts after pre-release versions
            return (1,)

        # Pre-release exists: sorts before non-pre-release
        key_parts = []
        for identifier in prerelease_ids:
            if identifier.isdigit():
                # Numeric identifier: (0, numeric_value)
                key_parts.append((0, int(identifier)))
            else:
                # Non-numeric identifier: (1, string_value)
                key_parts.append((1, identifier))

        return (0, tuple(key_parts))

    def sort_key(item):
        index, version = item
        major, minor, patch, prerelease_ids = parse_version(version)
        return (major, minor, patch, prerelease_key(prerelease_ids), index)

    indexed_versions = [(i, v) for i, v in enumerate(versions)]
    sorted_versions = sorted(indexed_versions, key=sort_key)
    return [v for _, v in sorted_versions]

